import { buscarEmbarcacionRepository, buscarTripulanteRepository, asignarTripulanteRepository } from './repository.mjs';

export class ReferenciaInexistenteError extends Error {}

export async function asignarTripulanteService(embarcacionId, tripulanteId, rol) {
  const embarcacion = await buscarEmbarcacionRepository(embarcacionId);
  const tripulante = await buscarTripulanteRepository(tripulanteId);
  if (!embarcacion || !tripulante) {
    throw new ReferenciaInexistenteError('No existe la embarcacion o el tripulante');
  }
  return asignarTripulanteRepository(embarcacionId, tripulanteId, rol);
}

import { asignarTripulanteService, ReferenciaInexistenteError } from './service.mjs';

export async function handler(event) {
  const embarcacionId = Number(event.pathParameters.embarcacionId);
  const { tripulanteId, rol } = JSON.parse(event.body);
  try {
    const asignacion = await asignarTripulanteService(embarcacionId, tripulanteId, rol);
    return { statusCode: 201, body: JSON.stringify(asignacion) };
  } catch (error) {
    if (error instanceof ReferenciaInexistenteError) {
      return { statusCode: 404, body: JSON.stringify({ message: error.message }) };
    }
    if (error.name === 'ConditionalCheckFailedException') {
      return { statusCode: 409, body: JSON.stringify({ message: 'El tripulante ya está asignado a esa embarcacion' }) };
    }
    throw error;
  }
}

